Q=pathlib.Path(__file__).resolve().parents[1];R=Q/'composition-recovery';A=R/'release-current-head'
def sha(b):return hashlib.sha256(b).hexdigest()
def build(source_repository,manifest=None):
 source_repository=pathlib.Path(source_repository);context=json.loads((A/'context.json').read_text());source=context['sourceCommit'];manifest=pathlib.Path(manifest or A/'release-gate-manifest.json');m=json.loads(manifest.read_text());assert m['releaseSourceCommit']==source,'ACTIVE_SOURCE_MANIFEST_MISMATCH'
